package top.dcpstudios.calendarwidget;
import android.app.AlertDialog;

import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

final class VisualStyles {
 static final String[] COLORS={"#287F73","#356DC2","#8654AE","#AD6430","#B94761","#536B85","#77852E","#378499"};
 static JSONObject config(MainActivity a){try{return new JSONObject(CalendarStore.prefs(a).getString("visual_styles","{}"));}catch(Exception e){return new JSONObject();}}
 static String message(JSONObject m){JSONObject p=m.optJSONObject("payload");if(p!=null){JSONArray tags=p.optJSONArray("categories");if(tags!=null&&tags.length()>0)return tags.optString(0);if(!p.optString("category").isEmpty())return p.optString("category");if(!p.optString("message_kind").isEmpty())return p.optString("message_kind");}return m.optString("source").equals("canvas")?"作业提醒":"一般消息";}
 static String event(MainActivity a,CalendarData.Event e){String chosen=CalendarStore.prefs(a).getString("event_category_"+e.uid,"");if(!chosen.isEmpty())return chosen;return e.uid.startsWith("llm-")?"智能日程":e.uid.startsWith("timetable-")?"课程":"作业";}
 static int color(MainActivity a,String tag){int value=rawColor(a,tag);return a.dark?blend(value,Color.WHITE,.35f):value;} static int rawColor(MainActivity a,String tag){int index=(tag.hashCode()&0x7fffffff)%COLORS.length;if(tag.contains("课程")||tag.equals("课程群"))index=1;else if(tag.contains("工作"))index=0;else if(tag.contains("科研"))index=2;else if(tag.startsWith("A")||tag.startsWith("a"))index=4;else if(tag.startsWith("B")||tag.startsWith("b"))index=3;else if(tag.startsWith("C")||tag.startsWith("c"))index=5;int result;try{result=Color.parseColor(config(a).optJSONObject(tag)==null?COLORS[index]:config(a).getJSONObject(tag).optString("color",COLORS[index]));}catch(Exception e){result=Color.parseColor(COLORS[index]);}return result;}
 static int blend(int x,int y,float f){return Color.rgb((int)(Color.red(x)*(1-f)+Color.red(y)*f),(int)(Color.green(x)*(1-f)+Color.green(y)*f),(int)(Color.blue(x)*(1-f)+Color.blue(y)*f));}
 static void apply(MainActivity a,View view,String tag){JSONObject row=config(a).optJSONObject(tag);String style=row==null?"柔和底色":row.optString("style","柔和底色");int color=color(a,tag);GradientDrawable bg=a.bg(style.equals("柔和底色")?blend(a.surface,color,a.dark?.14f:.07f):a.surface,12);if(style.equals("彩色描边"))bg.setStroke(a.d(1),blend(a.surface,color,.55f));view.setBackground(bg);}
 static TextView badge(MainActivity a,String tag){TextView label=a.text("●  "+tag,10,color(a,tag));label.setLayoutParams(new LinearLayout.LayoutParams(-2,-2));label.setPadding(a.d(8),a.d(4),a.d(8),a.d(4));label.setBackground(a.bg(blend(a.surface,color(a,tag),a.dark?.15f:.09f),6));return label;}
 static LinkedHashSet<String> tags(MainActivity a){LinkedHashSet<String> tags=new LinkedHashSet<>(Arrays.asList("课程群","工作群","科研群","A级联系人","B级联系人","C级联系人","一般消息","作业提醒","课程","作业","智能日程","会议","任务","个人安排"));JSONObject settings=AttentionSettings.state(a).optJSONObject("settings");if(settings!=null){JSONObject categories=settings.optJSONObject("categories");if(categories!=null)for(String kind:new String[]{"group","contact"}){JSONArray list=categories.optJSONArray(kind);if(list!=null)for(int i=0;i<list.length();i++)tags.add(list.optString(i));}}Iterator<String> keys=config(a).keys();while(keys.hasNext())tags.add(keys.next());return tags;}
 static void show(MainActivity a){a.base("visual_styles");a.root.addView(a.button("‹ 设置",a::settings));a.screenTitle("分类外观","颜色与标签同时显示 · 多分类使用第一项作为主色");ScrollView scroll=new ScrollView(a);LinearLayout list=a.column();scroll.addView(list);a.root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));for(String tag:tags(a)){LinearLayout row=a.column();row.setPadding(a.d(14),a.d(12),a.d(14),a.d(12));apply(a,row,tag);row.addView(badge(a,tag));TextView text=a.text("点击配置颜色与卡片样式  ›",12,a.muted);text.setPadding(0,a.d(8),0,0);row.addView(text);row.setOnClickListener(v->edit(a,tag));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.d(10);list.addView(row,lp);}a.root.addView(a.button("新增样式分类",()->{EditText input=new EditText(a);new android.app.AlertDialog.Builder(a).setTitle("分类名称").setView(input).setPositiveButton("添加",(d,w)->{String name=input.getText().toString().trim();if(!name.isEmpty())edit(a,name);}).setNegativeButton("取消",null).show();}));}
 static void edit(MainActivity a,String tag){LinearLayout box=a.column();box.setPadding(a.d(20),a.d(12),a.d(20),a.d(12));EditText input=new EditText(a);JSONObject old=config(a).optJSONObject(tag);input.setSingleLine();input.setText(String.format(Locale.US,"#%06X",rawColor(a,tag)&0xFFFFFF));box.addView(a.text("颜色 · #RRGGBB",12,a.muted));box.addView(input);LinearLayout palette=new LinearLayout(a);for(String hex:COLORS){View dot=new View(a);dot.setBackground(a.bg(Color.parseColor(hex),16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,a.d(32),1);lp.setMargins(a.d(2),a.d(8),a.d(2),a.d(8));palette.addView(dot,lp);dot.setContentDescription(hex);dot.setOnClickListener(v->input.setText(hex));}box.addView(palette);String[] styles={"柔和底色","彩色描边","仅标签"};Ui.Choice choice=new Ui.Choice(a,styles,old==null?0:Math.max(0,Arrays.asList(styles).indexOf(old.optString("style"))),3);box.addView(choice);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(a).setTitle(tag).setView(box).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{String hex=input.getText().toString().trim();if(!hex.matches("#[0-9a-fA-F]{6}"))throw new Exception("请输入 #RRGGBB 颜色");JSONObject cfg=config(a);cfg.put(tag,new JSONObject().put("color",hex).put("style",styles[choice.getSelectedItemPosition()]));CalendarStore.prefs(a).edit().putString("visual_styles",cfg.toString()).apply();dialog.dismiss();show(a);}catch(Exception e){a.error(e);}}));dialog.show();}
 static void assign(MainActivity a,CalendarData.Event event){String[] values=tags(a).toArray(new String[0]);Ui.select(a,"日程分类",values,Arrays.asList(values).indexOf(event(a,event)),n->{CalendarStore.prefs(a).edit().putString("event_category_"+event.uid,values[n]).apply();a.agenda();});}
 static int courseColor(MainActivity a,String course,int index){String saved=CalendarStore.prefs(a).getString("course_color_"+course,"");try{return Color.parseColor(saved);}catch(Exception ignored){}return Color.parseColor(COLORS[(index&0x7fffffff)%COLORS.length]);}
 static void canvasColors(MainActivity a){LinearLayout box=a.column();LinkedHashSet<String> names=new LinkedHashSet<>();for(CalendarData.Event e:CalendarStore.read(a))if(!e.course.isEmpty())names.add(e.course);for(String key:names){TextView row=a.text(key,13,a.ink);row.setPadding(a.d(12),a.d(12),a.d(12),a.d(12));row.setBackground(a.bg(courseColor(a,key,key.hashCode()),8));row.setOnClickListener(v->{EditText input=new EditText(a);input.setSingleLine();input.setText(String.format(Locale.US,"#%06X",courseColor(a,key,key.hashCode())&0xffffff));new AlertDialog.Builder(a).setTitle(key).setView(input).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{try{Color.parseColor(input.getText().toString());CalendarStore.prefs(a).edit().putString("course_color_"+key,input.getText().toString()).apply();canvasColors(a);}catch(Exception ex){a.error(ex);}}).show();});box.addView(row,new LinearLayout.LayoutParams(-1,-2));}new AlertDialog.Builder(a).setTitle("Canvas 科目颜色").setView(box).setPositiveButton("关闭",null).show();}
}
